{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    """Return (moves, goal_bucket, other_bucket_liters) using BFS over states."""
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two) or goal < 0:
        raise ValueError("goal is impossible to reach")

    sizes = (bucket_one, bucket_two)
    start = (bucket_one, 0) if start_bucket == "one" else (0, bucket_two)
    s = 0 if start_bucket == "one" else 1
    o = 1 - s

    def forbidden(state):
        return state[s] == 0 and state[o] == sizes[o]

    def neighbors(state):
        a, b = state
        pour_ab = min(a, bucket_two - b)
        pour_ba = min(b, bucket_one - a)
        return [
            (bucket_one, b), (a, bucket_two),
            (0, b), (a, 0),
            (a - pour_ab, b + pour_ab),
            (a + pour_ba, b - pour_ba),
        ]

    queue = deque([(start, 1)])
    seen = {start}
    while queue:
        state, moves = queue.popleft()
        if state[0] == goal:
            return moves, "one", state[1]
        if state[1] == goal:
            return moves, "two", state[0]
        for nxt in neighbors(state):
            if nxt in seen or forbidden(nxt):
                continue
            seen.add(nxt)
            queue.append((nxt, moves + 1))

    raise ValueError("goal is impossible to reach")
"}

